mapper.select:
SELECT p.position_id AS id, p.position_name, p.position_code, p.department_id, d.dept_name AS department, p.description, p.employee_count, p.head_count, p.status, p.create_time, p.update_time, p.created_by, p.updated_by, p.deleted, COALESCE(d.sort_order, 999) AS departmentSortOrder FROM positions p LEFT JOIN departments d ON p.department_id = d.department_id WHERE p.deleted = 0
AND p.department_id = #{departmentId}
AND p.status = #{status}
AND (p.position_name ILIKE #{keyword} OR p.position_code ILIKE #{keyword})
ORDER BY COALESCE(d.sort_order, 999), p.position_code
